<?php require __DIR__.'/layout.php'; if(!user()) {header('Location: index.php?view=login');exit;} page_start('chat.php','Messages'); $u=user(); $peers=query('SELECT id,full_name,role FROM users WHERE id<>? ORDER BY full_name','i',[$u['id']])->get_result()->fetch_all(MYSQLI_ASSOC); $receiver=(int)($_GET['receiver'] ?? ($peers[0]['id'] ?? 0)); ?>
<div class="page-heading"><div><div class="eyebrow">KEEP THE CONVERSATION LOCAL</div><h1>Good connections start here.</h1><p>Discuss material quality, terms and pickup with your partners.</p></div></div><div class="chat-shell"><aside class="contacts"><h2>Conversations</h2><?php foreach($peers as $p): ?><a href="chat.php?receiver=<?=$p['id']?>" class="<?=$receiver===$p['id']?'selected':''?>"><span class="avatar"><?=esc(strtoupper(substr($p['full_name'],0,1)))?></span><div><b><?=esc($p['full_name'])?></b><small><?=esc(ucfirst($p['role']))?></small></div></a><?php endforeach ?></aside><section class="chat-main"><div class="chat-top"><b><?php foreach($peers as $p) if($p['id']===$receiver) echo esc($p['full_name']); ?></b><select id="speech-language" class="form-select form-select-sm"><option value="en-US">English</option><option value="ar-IQ">العربية</option><option value="ckb-IQ">کوردی</option></select></div><div id="messages" data-user="<?=$u['id']?>" data-receiver="<?=$receiver?>" aria-live="polite"></div><form id="message-form" class="composer"><input type="hidden" name="receiver" value="<?=$receiver?>"><input type="hidden" name="action" value="send_message"><div id="attachment-name" class="muted"></div><textarea name="message_text" id="message-text" placeholder="Write a message..." aria-label="Message" rows="2"></textarea><div class="composer-tools"><label class="icon-btn" title="Attach image, video or PDF"><i data-lucide="paperclip"></i><input type="file" name="media" id="attachment" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm,audio/webm,audio/ogg,audio/mpeg,application/pdf" hidden></label><label class="icon-btn" title="Take a photo"><i data-lucide="camera"></i><input type="file" id="capture" accept="image/*" capture="environment" hidden></label><button type="button" id="dictate" class="icon-btn" title="Dictate message"><i data-lucide="mic"></i></button><button type="button" id="record" class="icon-btn" title="Record voice message"><i data-lucide="audio-lines"></i></button><span id="record-status" class="muted"></span><button class="btn btn-green ms-auto" aria-label="Send message"><i data-lucide="send"></i>Send</button></div></form></section></div>
<?php page_end(); ?>
